func firstBroken(_ crashed: [Bool]) -> Int {
    var low = 0
    var high = crashed.count
    while low < high {
        let mid = low + (high - low) / 2
        if crashed[mid] {
            high = mid
        } else {
            low = mid + 1
        }
    }
    return low
}
